"""
Set of keywords useful in Precondition/Postcondition
"""

import os
import logging
import time
from functools import partial
from taf.rfrl.utilities.test_config import DefaultFileLocation
from taf.rfrl.utilities.threads import with_threading_lock
from taf.rfrl.utilities.robot.general import run_robot_keyword, get_builtin_value, \
    get_robot_builtin_instance_and_import_if_needed


def download_bts_configuration(log_dir=None, bts_type='GNB', bts_id=0):
    """
    Downloads BTS configuration files to the specified directory.
    :param log_dir: Directory where the configuration files will be saved.
    :param bts_type: Type of BTS (GNB/ENB).
    :param bts_id: ID of BTS - related to the BTS configuration file.
    :return: Dictionary with the configuration files. eg:
    {
        'BTS': '/log_dir/REST_GNB0_DU0_current_scf.xml',
        'ASIR': '/log_dir/REST_GNB0_ASIR_current_scf.xml',
    }
    """
    results = {}
    _import_require_libraries_to_robot_namespaces()
    if log_dir is None:
        log_dir = get_builtin_value('OUTPUT_DIR')
    btype = bts_type.lower()

    bts_config = run_robot_keyword(f'{btype}bbu.Get BTS Configuration File',
                                   f'bts_id={bts_id}', f'local_dir={log_dir}')
    results['BTS'] = bts_config
    # TODO add 'If' RobotWrapper
    if run_robot_keyword(f'{btype}scf.Is ASIR Configuration', f'bts_id={bts_id}'):
        asir_config = run_robot_keyword(f'{btype}asir.Get Current SCF File',
                                        f'bts_id={bts_id}', f'local_dir_path={log_dir}')
        results['ASIR'] = asir_config

    return results


def verify_bts_is_up_and_on_air(bts_type='GNB', bts_id=0):
    """
    Verifies if the BTS is up and on air.
    :param bts_type: Type of BTS (GNB/ENB).
    :param bts_id: ID of BTS - related to the BTS configuration file.
    """
    _import_require_libraries_to_robot_namespaces()
    btype = bts_type.lower()

    # TODO
    #       # add checking all SMODs
    #       # add checking all BBMODs(self.check_bbmod)

    run_robot_keyword(f'{btype}ru.Verify All Radio Units are Online', f'bts_id={bts_id}')
    run_robot_keyword(f'{btype}cell.Verify All Cells are OnAir', f'bts_id={bts_id}')
    run_robot_keyword(f'{btype}bbu.Verify BTS is OnAir', f'bts_id={bts_id}')
    if run_robot_keyword(f'{btype}scf.Is ASIR Configuration', f'bts_id={bts_id}'):
        run_robot_keyword(f'{btype}asir.Verify All Antennas are Enabled', f'bts_id={bts_id}')
        run_robot_keyword(f'{btype}asir.Verify Status of All ASIR Cells is Operational', f'bts_id={bts_id}')


def wait_until_bts_is_up_and_on_air(bts_type='GNB', bts_id=0, timeout=300):
    """
    Waits until the BTS is up and on air.
    :param bts_type: Type of BTS (GNB/ENB).
    :param bts_id: ID of BTS - related to the BTS configuration file.
    :param timeout: Time in seconds to wait for the BTS to be up and on air.
    """
    _import_require_libraries_to_robot_namespaces()
    btype = bts_type.lower()
    wait_till = partial(run_robot_keyword, 'Wait Until Keyword Succeeds', f'{timeout} sec', '10 sec')

    # TODO - see TODO's from verify_bts_is_up_and_on_air

    wait_till(f'{btype}ru.Verify All Radio Units are Online', f'bts_id={bts_id}')
    wait_till(f'{btype}cell.Verify All Cells are OnAir', f'bts_id={bts_id}')
    wait_till(f'{btype}bbu.Verify BTS is OnAir', f'bts_id={bts_id}')
    if run_robot_keyword(f'{btype}scf.Is ASIR Configuration', f'bts_id={bts_id}'):
        wait_till(f'{btype}asir.Verify All Antennas are Enabled', f'bts_id={bts_id}')
        wait_till(f'{btype}asir.Verify Status of All ASIR Cells is Operational', f'bts_id={bts_id}')


def perform_bts_commissioning(bts_id=0, bts_type='GNB', scf_path=None, asir_scf_path=None, prefix_tag=None,
                              wait_for_on_air=True, force_reconnect=True, asir_commissioning=True, interface='lmp',
                              commissioning_timeout=400, asir_commissioning_timeout=120, wait_for_on_air_timeout=300,
                              delay_for_checking_on_air=30, skip_parameter_relation_errors=True):
    """
    Perform full commissioning on BTS and wait for BTS to be on air.
    :param bts_id: BTS(eNB/gNB) id - related to Test Line configuration
    :param bts_type: BTS type - ENB or GNB
    :param scf_path: scf_path to BTS - if not set then default will be selected
                     check: https://confluence.ext.net.nokia.com/display/5GPzKRK/TL+Commissioning
    :param asir_scf_path: scf_path to ASIR - if not set then default will be selected
                         check: https://confluence.ext.net.nokia.com/display/5GPzKRK/TL+Commissioning
    :param prefix_tag: scf_path to BTS - if scf_path not passed then default with specific prefix_tag will be selected
    :param wait_for_on_air: True/False - If True - wait for BTS to be on air
    :param force_reconnect: True/False - If True - first disconnect if already connected with BTS
    :param asir_commissioning: True/False - If True - perform ASIR commissioning if ASIR is present in configuration.
    :param interface: Interface to connect with BTS lmp/mplane
    :param commissioning_timeout: Time in seconds to wait for BTS commissioning process finishes
    :param asir_commissioning_timeout: Time in seconds to wait for ASIR commissioning process finishes
    :param wait_for_on_air_timeout: Time in seconds to wait for BTS to be on air
    :param delay_for_checking_on_air: Time in seconds to wait before checking OnAir
    :param skip_parameter_relation_errors: True/False - If True - skip parameter relation errors
                                           during BTS commissioning
    """

    _import_require_libraries_to_robot_namespaces()
    bts_type = bts_type.upper()
    btype = bts_type.lower()
    scf_path = scf_path if scf_path else _get_default_scf_for_bts(bts_id=bts_id,
                                                                  bts_type=bts_type,
                                                                  prefix_tag=prefix_tag)

    logging.debug("Performing full commissioning on {}{} with scf: {}".format(bts_type, bts_id, scf_path))
    run_robot_keyword(f'{btype}scf.Connect',
                      f'bts_id={bts_id}',
                      f'interface={interface}',
                      f'force=${{{force_reconnect}}}')
    validation_status = run_robot_keyword('Run Keyword And Ignore Error', f'{btype}scf.Validate Configuration',
                                          f'bts_id={bts_id}',
                                          f'scf_file={scf_path}',
                                          )
    if validation_status[0] == 'FAIL':
        logging.warning("Validation SCF Failed - Please consider adapt your SCF\n{}".format(validation_status[1]))

    run_robot_keyword(f'{btype}scf.Perform BTS Full Commissioning',
                      f'bts_id={bts_id}',
                      f'scf_file={scf_path}',
                      f'skip_parameter_relation_errors=${{{skip_parameter_relation_errors}}}',
                      'should_activate=${True}',
                      'validate_scf=${False}',
                      f'timeout={commissioning_timeout}')

    run_robot_keyword(f'{btype}scf.Connect',
                      f'bts_id={bts_id}',
                      'interface=mplane',
                      'force=${True}')

    is_asir_configuration = run_robot_keyword(f'{btype}scf.Is ASIR Configuration', f'bts_id={bts_id}')
    if asir_commissioning and is_asir_configuration:
        asir_scf_path = asir_scf_path if asir_scf_path else _get_default_scf_for_asir_hub(bts_id, prefix_tag, bts_type)
        run_robot_keyword(f'{btype}asir.connect',
                          f'bts_id={bts_id}',
                          'force=${True}'
                          'timeout=${240}')
        run_robot_keyword(f'{btype}asir.Perform ASIR Commissioning',
                          f'bts_id={bts_id}',
                          f'scf_path={asir_scf_path}',
                          'migrate_nidd=${True}',
                          f'timeout={asir_commissioning_timeout}')

    logging.debug("Sleep {} seconds before checking OnAir".format(delay_for_checking_on_air))
    time.sleep(delay_for_checking_on_air)
    if wait_for_on_air:
        run_robot_keyword('taf.rfrl.bts.operations.Wait Until BTS is Up and On Air',
                          f'bts_id={bts_id}',
                          f'bts_type={bts_type}',
                          f'timeout={wait_for_on_air_timeout}')


@with_threading_lock
def _import_require_libraries_to_robot_namespaces():
    required_libraries = (
        (None, 'taf.rfrl.bts.operations'),
        ('gnbbbu', 'taf.rfrl.bts.devices.du.du_operations.GnbDuOperations'),
        ('enbbbu', 'taf.rfrl.bts.devices.du.du_operations.EnbDuOperations'),
        ('gnbscf', 'taf.rfrl.bts.devices.du.commissioning.GnbCommissioning'),
        ('enbscf', 'taf.rfrl.bts.devices.du.commissioning.EnbCommissioning'),
        ('gnbasir', 'taf.rfrl.bts.devices.asir.asir_operations.GnbAsirHubOperations'),
        ('enbasir', 'taf.rfrl.bts.devices.asir.asir_operations.EnbAsirHubOperations'),
        ('gnbru', 'taf.rfrl.bts.devices.ru.ru_operations.GnbRuOperations'),
        ('enbru', 'taf.rfrl.bts.devices.ru.ru_operations.EnbRuOperations'),
        ('gnbcell', 'taf.rfrl.bts.devices.du.cell_operations.GnbCellOperations'),
        ('enbcell', 'taf.rfrl.bts.devices.du.cell_operations.EnbCellOperations'),
    )
    for name, lib_path in required_libraries:
        get_robot_builtin_instance_and_import_if_needed(name, lib_path)


def _get_default_scf_for_bts(bts_id=0, prefix_tag=None, bts_type='GNB'):
    dfl = DefaultFileLocation()
    commission_dir = dfl.get_commissioning_dir()
    scf_name = dfl.get_default_scf_name(bts_type, bts_id, prefix_tag)
    scf_path = os.path.join(commission_dir, scf_name)

    return scf_path


def _get_default_scf_for_asir_hub(bts_id=0, prefix_tag=None, bts_type='GNB'):
    dfl = DefaultFileLocation()
    commission_dir = dfl.get_commissioning_dir()
    scf_name = dfl.get_default_scf_name(bts_type, bts_id, prefix_tag, sub_device='ASIR')
    scf_path = os.path.join(commission_dir, scf_name)

    return scf_path
